// Tutoring team pages (generated by scripts/build-tutors.mjs).
//
// 1. tutors/ : filters the tutor cards by subject, level and format. The
//    choice is kept in the address (?subject=physics&level=high-school) so
//    a filtered list can be linked to. Without JavaScript every tutor shows.
// 2. tutors/inquire/ : the inquiry form. ?tutor=<slug> picks that tutor.
//    Sends to the Supabase table public.tutoring_inquiries with the public
//    anon key, which can only add a row (supabase/tutoring.sql). If sending
//    isn't possible, the visitor keeps what they typed and gets an email
//    link with their answers filled in.
(function () {
  'use strict';

  var track = window.mathleteTrack || function () {};
  var params = new URLSearchParams(location.search);

  // ---------- 1. directory filters ----------
  var filterForm = document.getElementById('tutor-filters');
  if (filterForm) {
    var cards = Array.prototype.slice.call(document.querySelectorAll('#tutor-grid .tutor-card'));
    var selects = Array.prototype.slice.call(filterForm.querySelectorAll('select[data-filter]'));
    var count = document.getElementById('tutor-count');
    var empty = document.getElementById('tutor-empty');
    var ATTR = { subject: 'data-subjects', level: 'data-levels', format: 'data-formats' };

    selects.forEach(function (s) {
      var want = params.get(s.getAttribute('data-filter'));
      if (want && s.querySelector('option[value="' + CSS.escape(want) + '"]')) s.value = want;
    });

    var apply = function (fromUser) {
      var shown = 0;
      cards.forEach(function (card) {
        var ok = selects.every(function (s) {
          return !s.value || (card.getAttribute(ATTR[s.getAttribute('data-filter')]) || '').split(' ').indexOf(s.value) !== -1;
        });
        card.hidden = !ok;
        if (ok) shown++;
      });
      empty.hidden = shown > 0;
      var any = selects.some(function (s) { return s.value; });
      count.textContent = any
        ? (shown === 1 ? '1 tutor matches.' : shown + ' tutors match.')
        : (cards.length === 1 ? '1 tutor.' : cards.length + ' tutors.');
      if (fromUser) {
        var q = new URLSearchParams();
        selects.forEach(function (s) { if (s.value) q.set(s.getAttribute('data-filter'), s.value); });
        var qs = q.toString();
        history.replaceState(null, '', location.pathname + (qs ? '?' + qs : '') + location.hash);
        track('tutor_directory_filter');
      }
    };

    filterForm.addEventListener('change', function () { apply(true); });
    filterForm.addEventListener('reset', function () { setTimeout(function () { apply(true); }, 0); });
    filterForm.addEventListener('submit', function (e) { e.preventDefault(); });
    filterForm.hidden = false;
    apply(false);
  }

  // ---------- 2. inquiry form ----------
  var form = document.getElementById('tutor-inquiry-form');
  if (!form) return;

  var cfg = window.MATHLETE_SUPABASE || {};
  var configured = !!(cfg.url && cfg.anonKey);
  var OWNER_EMAIL = 'wcmalfeld@gmail.com';
  var EMAIL_RE = /^[^@\s]+@[^@\s]+\.[^@\s]+$/;
  var notice = document.getElementById('inquiry-notice');
  var button = document.getElementById('inquiry-button');
  var buttonText = button.textContent;
  function field(name) { return form.elements.namedItem(name); }
  function text(s) { return document.createTextNode(s); }

  // Fill in the tutor the visitor came from.
  var tutorSelect = field('preferred_tutor');
  var chosen = document.getElementById('tutor-chosen');
  var fromTutor = params.get('tutor');
  if (fromTutor && tutorSelect.querySelector('option[value="' + CSS.escape(fromTutor) + '"]')) {
    tutorSelect.value = fromTutor;
    var name = tutorSelect.options[tutorSelect.selectedIndex].text;
    chosen.replaceChildren(text('You’re asking about '), Object.assign(document.createElement('strong'), { textContent: name }), text('. You can change this below.'));
    chosen.hidden = false;
  }

  track('tutor_inquiry_page_view');
  var started = false;
  form.addEventListener('input', function () {
    if (started) return;
    started = true;
    track('tutor_inquiry_form_start');
  });

  var rules = [
    { el: 'ti-name', error: 'ti-name-error', check: function () { return field('name').value.trim() ? '' : 'Enter your name.'; } },
    { el: 'ti-email', error: 'ti-email-error', check: function () {
        var v = field('email').value.trim();
        if (!v) return 'Enter your email address.';
        return EMAIL_RE.test(v) ? '' : 'Enter an email address like name@example.com.';
      } },
    { el: 'ti-level', error: 'ti-level-error', check: function () { return field('student_level').value ? '' : 'Choose the student’s grade or level.'; } },
    { el: 'ti-subject', error: 'ti-subject-error', check: function () { return field('subject').value ? '' : 'Choose a subject (“Not sure” is fine).'; } },
    { el: 'ti-help', error: 'ti-help-error', check: function () { return field('help_with').value.trim() ? '' : 'Tell us briefly what you’d like help with.'; } },
    { el: 'ti-consent', error: 'ti-consent-error', check: function () { return field('consent').checked ? '' : 'Please agree to be contacted so we can reply.'; } }
  ];

  function setError(rule, msg) {
    var el = document.getElementById(rule.el);
    var err = document.getElementById(rule.error);
    err.textContent = msg;
    err.hidden = !msg;
    if (msg) el.setAttribute('aria-invalid', 'true');
    else el.removeAttribute('aria-invalid');
  }

  function validate() {
    return rules.filter(function (rule) {
      var msg = rule.check();
      setError(rule, msg);
      return !!msg;
    });
  }

  function recheck(e) {
    rules.forEach(function (rule) {
      var el = document.getElementById(rule.el);
      if (el.getAttribute('aria-invalid') === 'true' && el === e.target) setError(rule, rule.check());
    });
  }
  form.addEventListener('change', recheck);
  form.addEventListener('input', recheck);

  function show(kind, nodes) {
    notice.className = 'notice notice--' + kind;
    notice.replaceChildren.apply(notice, nodes);
    notice.setAttribute('role', kind === 'error' ? 'alert' : 'status');
    notice.hidden = false;
  }

  function chosenText(name) {
    var el = field(name);
    if (el && el.options) return el.options[el.selectedIndex].text;
    var r = form.querySelector('[name="' + name + '"]:checked');
    return r ? r.parentNode.textContent.trim() : '';
  }

  function collect() {
    var str = function (v) { v = (v || '').trim(); return v || null; };
    var fmt = form.querySelector('[name="format"]:checked');
    return {
      name: field('name').value.trim(),
      email: field('email').value.trim(),
      student_level: field('student_level').value,
      subject: field('subject').value,
      preferred_tutor: tutorSelect.value || 'no-preference',
      help_with: field('help_with').value.trim(),
      format: fmt ? fmt.value : 'no-preference',
      additional_info: str(field('additional_info').value),
      consent: field('consent').checked,
      source_page: (location.pathname + location.search).slice(0, 200)
    };
  }

  function mailtoLink(label) {
    var d = collect();
    var lines = [
      'Tutoring inquiry',
      'Name: ' + d.name,
      'Email: ' + d.email,
      'Level: ' + chosenText('student_level'),
      'Subject: ' + chosenText('subject'),
      'Preferred tutor: ' + chosenText('preferred_tutor'),
      'Format: ' + chosenText('format'),
      '',
      d.help_with
    ];
    if (d.additional_info) lines.push('', d.additional_info);
    var a = document.createElement('a');
    a.href = 'mailto:' + OWNER_EMAIL + '?subject=' + encodeURIComponent('Tutoring inquiry') + '&body=' + encodeURIComponent(lines.join('\n'));
    a.textContent = label;
    return a;
  }

  function showFailure(intro) {
    show('error', [
      text(intro + ' Everything you entered is still here. You can try again, or '),
      mailtoLink('send it by email instead'),
      text(' (your answers are filled in), or write to ' + OWNER_EMAIL + '.')
    ]);
    notice.focus();
  }

  function send(data) {
    var url = cfg.url.replace(/\/+$/, '') + '/rest/v1/tutoring_inquiries';
    var headers = { 'Content-Type': 'application/json', apikey: cfg.anonKey, Prefer: 'return=minimal' };
    if (/^eyJ/.test(cfg.anonKey)) headers.Authorization = 'Bearer ' + cfg.anonKey;
    return fetch(url, { method: 'POST', headers: headers, body: JSON.stringify(data) });
  }

  function succeed() {
    form.hidden = true;
    var book = document.createElement('a');
    book.href = 'book.html';
    book.textContent = 'book a session';
    book.setAttribute('data-track', 'book_cta_tutor_inquiry_done');
    show('success', [
      Object.assign(document.createElement('strong'), { textContent: 'Thanks for reaching out! ' }),
      text('The Mathlete team will be in touch soon to learn a little more about what you’re looking for and help find the right tutoring fit. If you’d rather pick a time now, you can also '),
      book,
      text('.')
    ]);
    notice.focus();
    track('tutor_inquiry_submit_success');
  }

  form.addEventListener('submit', function (e) {
    e.preventDefault();
    notice.hidden = true;
    if (field('website').value) return succeed();   // spam trap

    var failed = validate();
    if (failed.length) {
      show('error', [text(failed.length === 1
        ? 'One thing needs fixing before this can be sent: ' + document.getElementById(failed[0].error).textContent
        : failed.length + ' things need fixing before this can be sent. They’re marked below.')]);
      document.getElementById(failed[0].el).focus();
      return;
    }

    if (!configured || typeof fetch !== 'function') {
      track('tutor_inquiry_submit_error');
      return showFailure('The form can’t send messages from here right now.');
    }

    button.disabled = true;
    button.textContent = 'Sending…';
    send(collect()).then(function (res) {
      if (res.ok) return succeed();
      track('tutor_inquiry_submit_error');
      showFailure(res.status === 429 || res.status >= 500
        ? 'The form is busy right now, so your inquiry wasn’t sent.'
        : 'Something went wrong and your inquiry wasn’t sent.');
    }).catch(function () {
      track('tutor_inquiry_submit_error');
      showFailure('Your inquiry couldn’t be sent. Check your connection.');
    }).then(function () {
      button.disabled = false;
      button.textContent = buttonText;
    });
  });
})();
